\set ON_ERROR_STOP on
begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
create temp table ck_ids(key text primary key,id uuid default gen_random_uuid(),token text);
insert into ck_ids(key) values('owner'),('secretary'),('clerk'),('other'),('super'),('show'),('other_show'),('exhibitor'),('section'),('session'),('entry'),('request');
grant all on ck_ids to authenticated,anon,service_role;
insert into auth.users(id) select id from ck_ids where key in ('owner','secretary','clerk','other','super');
insert into shows(id,name,owner_user_id,created_by,start_date,end_date)
select s.id,'Check-in release fixture',u.id,u.id,current_date,current_date from ck_ids s join ck_ids u on u.key='owner' where s.key in('show','other_show');
insert into role_assignments(user_id,show_id,role)
select id,(select id from ck_ids where key='show'),case when key='secretary' then 'admin'::app_role else 'reporting_clerk'::app_role end from ck_ids where key in('secretary','clerk');
insert into super_admins(user_id) select id from ck_ids where key='super';
insert into show_sections(id,show_id,kind,letter,judging_date)
select id,(select id from ck_ids where key='show'),'open','A',current_date from ck_ids where key='section';
insert into exhibitors(id,display_name,first_name,last_name,type,is_local_only,created_for_show_id,exhibitor_number)
select id,'Checkin Fixture','Checkin','Fixture','adult',true,(select id from ck_ids where key='show'),987654321 from ck_ids where key='exhibitor';
insert into entries(id,show_id,section_id,exhibitor_id,species,tattoo,breed,variety,sex,class_name,status)
select (select id from ck_ids where key='entry'),(select id from ck_ids where key='show'),(select id from ck_ids where key='section'),id,'rabbit','CK-1','Dutch','Black','Buck','Senior','entered' from ck_ids where key='exhibitor';
select set_config('request.jwt.claims',jsonb_build_object('sub',(select id from ck_ids where key='owner'),'role','authenticated')::text,true);
set local role authenticated;
select ok(user_can_manage_show_checkin_settings((select id from ck_ids where key='show')),'any show owner can manage check-in');
select lives_ok($$insert into show_checkin_settings(show_id,is_enabled,require_initials,require_signature) select id,true,true,true from ck_ids where key='show'$$,'owner can save through RLS');
update ck_ids set token=regenerate_show_checkin_portal_token(id) where key='show';
select ok((select length(token)>32 from ck_ids where key='show'),'owner can generate portal token');
reset role;
select set_config('request.jwt.claims',jsonb_build_object('sub',(select id from ck_ids where key='secretary'),'role','authenticated')::text,true);
set local role authenticated;
select ok(user_can_manage_show_checkin_settings((select id from ck_ids where key='show')),'assigned secretary can configure');
select ok(not user_can_manage_show_checkin_settings((select id from ck_ids where key='other_show')),'secretary cannot configure another show');
select lives_ok($$update show_checkin_settings set opens_at=now()-interval '1 hour',closes_at=now()+interval '1 hour' where show_id=(select id from ck_ids where key='show')$$,'secretary can save availability');
select is((select count(*)::int from show_checkin_settings where show_id=(select id from ck_ids where key='show') and opens_at is not null),1,'secretary update affected expected row');
reset role;
select set_config('request.jwt.claims',jsonb_build_object('sub',(select id from ck_ids where key='clerk'),'role','authenticated')::text,true);
set local role authenticated;
select ok(not user_can_manage_show_checkin_settings((select id from ck_ids where key='show')),'reporting clerk does not gain settings access');
select throws_ok($$select regenerate_show_checkin_portal_token((select id from ck_ids where key='show'))$$,'42501',null,'clerk cannot rotate QR');
reset role;
select set_config('request.jwt.claims',jsonb_build_object('sub',(select id from ck_ids where key='other'),'role','authenticated')::text,true);
set local role authenticated;
select throws_ok($$insert into show_checkin_settings(show_id) select id from ck_ids where key='other_show'$$,'42501',null,'unrelated user cannot insert settings');
with changed as (update show_checkin_settings set is_enabled=false where show_id=(select id from ck_ids where key='show') returning 1) select is(count(*)::int,0,'unrelated user cannot update settings') from changed;
select throws_ok($$select regenerate_show_checkin_portal_token((select id from ck_ids where key='show'))$$,'42501',null,'unrelated user cannot rotate QR');
reset role;
select set_config('request.jwt.claims',jsonb_build_object('sub',(select id from ck_ids where key='super'),'role','authenticated')::text,true);
set local role authenticated;
select ok(user_can_manage_show_checkin_settings((select id from ck_ids where key='show')),'superadmin keeps access');
reset role;
select set_config('request.jwt.claims','{"role":"anon"}',true);
set local role anon;
select throws_ok($$select user_can_manage_show_checkin_settings((select id from ck_ids where key='show'))$$,'42501',null,'anonymous cannot call settings helper');
select throws_ok($$select authenticate_exhibitor_checkin('wrong','1','Fixture')$$,'P0001',null,'invalid token rejected');
select throws_ok($$select authenticate_exhibitor_checkin((select token from ck_ids where key='show'),'wrong','Fixture')$$,'P0001',null,'wrong identity rejected');
reset role;
update ck_ids set token=(select exhibitor_number::text from exhibitors where id=ck_ids.id) where key='exhibitor';
set local role anon;
update ck_ids set token=authenticate_exhibitor_checkin((select token from ck_ids where key='show'),(select token from ck_ids where key='exhibitor'),'fixture')->>'session_token' where key='session';
select ok((select length(token)>32 from ck_ids where key='session'),'valid exhibitor verifies case-insensitive last name');
select lives_ok($$select get_exhibitor_checkin_portal_data((select token from ck_ids where key='session'))$$,'verified exhibitor can review entries');
select throws_ok($$select submit_exhibitor_checkin_change_request((select token from ck_ids where key='session'),(select id from ck_ids where key='entry'),'entry_edit','{"breed":"Dutch"}')$$,'P0001',null,'disabled entry changes rejected');
reset role;
update show_checkin_settings set entry_edit_permissions='{"ear_number":"automatic","sex":"approval"}',entry_edit_fee_cents='{"ear_number":100,"sex":250}' where show_id=(select id from ck_ids where key='show');
set local role anon;
select throws_ok($$select submit_exhibitor_checkin_change_request((select token from ck_ids where key='session'),(select id from ck_ids where key='other_show'),'entry_edit','{"ear_number":"OTHER"}')$$,'P0001',null,'session cannot change an unrelated entry');
select throws_ok($$select submit_exhibitor_checkin_change_request((select token from ck_ids where key='session'),(select id from ck_ids where key='entry'),'entry_edit','{"ear_number":"CK-2"}')$$,'P0001','This exhibitor does not have an account-backed cart. Please see the show secretary.','fee-bearing change for an unlinked exhibitor requires staff assistance');
reset role;
select is((select tattoo from entries where id=(select id from ck_ids where key='entry')),'CK-1','failed fee leaves original entry intact');
update exhibitors set email='checkin-fixture@example.invalid',owner_user_id=(select id from ck_ids where key='owner') where id=(select id from ck_ids where key='exhibitor');
set local role anon;
select is(submit_exhibitor_checkin_change_request((select token from ck_ids where key='session'),(select id from ck_ids where key='entry'),'entry_edit','{"ear_number":"CK-2"}')->>'status','approved','automatic change applies immediately');
update ck_ids set id=(submit_exhibitor_checkin_change_request((select token from ck_ids where key='session'),(select id from ck_ids where key='entry'),'entry_edit','{"sex":"Doe"}')->>'id')::uuid where key='request';
reset role;
select is((select tattoo from entries where id=(select id from ck_ids where key='entry')),'CK-2','automatic ear number saved');
select is((select sex from entries where id=(select id from ck_ids where key='entry')),'Buck','pending change does not alter entry');
select is((select sum(amount_cents)::int from show_checkin_fee_charges where show_id=(select id from ck_ids where key='show')),100,'only automatic change charged before approval');
select set_config('request.jwt.claims',jsonb_build_object('sub',(select id from ck_ids where key='secretary'),'role','authenticated')::text,true);
set local role authenticated;
select lives_ok($$select review_checkin_change_request((select id from ck_ids where key='request'),true,'Verified')$$,'secretary can approve change');
reset role;
select is((select sex from entries where id=(select id from ck_ids where key='entry')),'Doe','approved change saved');
select is((select sum(amount_cents)::int from show_checkin_fee_charges where show_id=(select id from ck_ids where key='show')),350,'approval fee charged once applied');
select set_config('request.jwt.claims','{"role":"anon"}',true);
set local role anon;
select throws_ok($$select complete_exhibitor_checkin((select token from ck_ids where key='session'),false,'CF','Checkin Fixture','no_receipt')$$,'P0001',null,'entry confirmation required');
select throws_ok($$select complete_exhibitor_checkin((select token from ck_ids where key='session'),true,'','Checkin Fixture','no_receipt')$$,'P0001',null,'initials enforced');
select throws_ok($$select complete_exhibitor_checkin((select token from ck_ids where key='session'),true,'CF','','no_receipt')$$,'P0001',null,'signature enforced');
select lives_ok($$select complete_exhibitor_checkin((select token from ck_ids where key='session'),true,'CF','Checkin Fixture','no_receipt')$$,'exhibitor completes check-in without emailing');
reset role;
select is((select status from show_checkin_records where show_id=(select id from ck_ids where key='show')),'completed','completion persisted');
update show_checkin_settings set closes_at=now()-interval '1 minute' where show_id=(select id from ck_ids where key='show');
set local role anon;
select throws_ok($$select authenticate_exhibitor_checkin((select token from ck_ids where key='show'),(select token from ck_ids where key='exhibitor'),'Fixture')$$,'P0001',null,'closed portal rejects new sessions');
select throws_ok($$select complete_exhibitor_checkin((select token from ck_ids where key='session'),true,'CF','Checkin Fixture','no_receipt')$$,null::text,null::text,'existing session cannot bypass closing');
reset role;
select * from finish();
rollback;
